const PREFIX_RE=new RegExp(`^[¤nmNM]?\\s*[${D}]{1,3}\\s*[,.]?\\s*$`), TAIL_PREFIX_RE=new RegExp(`[¤nmNM]\\s*[${D}]{1,3}\\s*[,.]?\\s*$`);
