  if(!img)throw new Error(t('imgErr'));
  const W=img.width,H=img.height,wk=await getWorker();
  // Progress text and bar for pass k of 4.
  const step=(k,txt)=>setProg(`${t('reading')} ${idx+1} ${t('of')} ${total}: ${file.name} · ${t('pass')} ${k}/4${txt?' · '+txt:''}`,(idx+(k-1)/4)/total);
  // 1) Rough read of the right half: find the tabs, narrow down the panel
  step(1);const rx=Math.floor(W*0.55);
  let rough=await ocrWords(wk,cropCanvas(img,rx,0,W-rx,H,2,1.3),rx,0,2);
  let kf=rough.find(w=>TAB_KAUF.test(w.text)), mk=rough.find(w=>TAB_MARKT.test(w.text)), glass=false;
  // Frontal glass kiosk (white text on a bright panel)? Use a threshold instead of contrast
  if(!kf&&!mk&&vocabScore(rough)<3){
    const r2=await ocrWords(wk,thresholdCanvas(cropCanvas(img,rx,0,W-rx,H,2,1.0),205),rx,0,2);
    const k2=r2.find(w=>TAB_KAUF.test(w.text)),m2=r2.find(w=>TAB_MARKT.test(w.text));
    if(k2||m2||vocabScore(r2)>=3){rough=r2;kf=k2;mk=m2;glass=true;}
  }
  const client=clientOf(rough);
  // Prepares a crop: threshold on glass kiosks, contrast otherwise.
  const prep=(x0,y0,w,h,sc,ct,th)=>glass?thresholdCanvas(cropCanvas(img,x0,y0,w,h,sc,1.0),th):cropCanvas(img,x0,y0,w,h,sc,ct);
  // Nothing found frontally -> angled shot: straighten it
  if(!kf&&!mk&&vocabScore(rough)<3){
    step(2,t('skewed'));
    let res=null,quad=null;
    const dims=W+'x'+H;
    for(const cand of [lastDims===dims?lastQuad:null,autoQuad(img,'R')]){if(!cand)continue;const r=await readWarped(wk,img,cand);if(r.score>=3){res=r;quad=cand;break;}}
    if(!res){setProg(`${t('reading')} ${idx+1} ${t('of')} ${total}: ${file.name} · ${t('cornerAsk')}`,idx/total);
      const q=await askCorners(img,file);if(!q){img.close&&img.close();throw new Error(t('skipped'));}
      res=await readWarped(wk,img,q);quad=q;}
    lastQuad=quad;lastDims=dims;
    step(4);const lq=autoQuad(img,'L');let L=[];
    if(lq){const lc=warpQuad(img,lq,2.5);L=await ocrWords(wk,thresholdCanvas(lc,205),0,0,1);}
    else{const lx=Math.floor(W*0.45);L=await ocrWords(wk,cropCanvas(img,0,0,lx,H,2,1.3),0,0,2);}
    img.close&&img.close();
    return{file:file.name,url:URL.createObjectURL(file),imgW:W,imgH:H,mtime:new Date(file.lastModified).toISOString(),ocr:'tesseract',skewed:true,client:clientOf([...res.R,...res.RB]),tabs:res.tabs,variants:[{tag:'L',words:L},{tag:'R',words:res.R},{tag:'RB',words:res.RB}]};
  }
  let px0=rx,px1=W,py0=0;
  // Panel width: the right edge lies about 0.08–0.12 W right of the word LOCAL/LOKALER, or 0.2 W right of BUY/KAUFEN
  if(kf){px0=Math.max(0,kf.x-W*0.02);py0=Math.max(0,kf.y-kf.h*0.5);px1=Math.min(W,Math.max(mk?mk.x+W*0.16:0,kf.x+W*0.22));}
  else if(mk){px0=Math.max(0,mk.x-W*0.06);py0=Math.max(0,mk.y-mk.h*0.5);px1=Math.min(W,mk.x+W*0.16);}
  // 2+3) Read the panel in two passes (normal and high contrast)
  step(2);let R=await ocrWords(wk,prep(px0,py0,px1-px0,H-py0,3,1.3,205),px0,py0,3);
  step(3);let RB=await ocrWords(wk,prep(px0,py0,px1-px0,H-py0,4,3.0,225),px0,py0,4);
  // Tabs: if one is missing in the rough read, look in the fine reads; if still missing, estimate its position from the other
  let fine=[...R,...RB];kf=kf||fine.find(w=>TAB_KAUF.test(w.text));mk=mk||fine.find(w=>TAB_MARKT.test(w.text));
  let tabs=tabBrightness(img,kf,mk),skewed=false;
